-- WoW Forever: Russian item names and texts for 4541 items that our hotfixes send to clients (item_sparse rows in our hotfix
-- SQL, the live hotfix lists and 2026_11_08_10/40) but that had no Russian row in our SQL, so Russian players saw them in English.
-- From the item hotfix cache (Cache\ADB\ruRU\DBCache.bin, build 70862) of a Russian player who sent us their cache folder on
-- 2026-11-08: the same records Blizzard sends to Russian clients. Existing Russian rows are kept: only missing rows and empty
-- names are filled, and only for items in item_sparse. Safe to run again.
DROP TEMPORARY TABLE IF EXISTS `tmp_ruru_item_sparse_locale`;
CREATE TEMPORARY TABLE `tmp_ruru_item_sparse_locale` (`ID` INT UNSIGNED NOT NULL, `locale` VARCHAR(4) NOT NULL, `Description_lang` MEDIUMTEXT, `Display3_lang` MEDIUMTEXT, `Display2_lang` MEDIUMTEXT, `Display1_lang` MEDIUMTEXT, `Display_lang` MEDIUMTEXT, `VerifiedBuild` INT NOT NULL, PRIMARY KEY (`ID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
