UPDATE `item_sparse_locale` l JOIN `tmp_ruru_item_sparse_locale` t ON t.`ID`=l.`ID` AND l.`locale`='ruRU' SET l.`Display_lang`=IF(COALESCE(l.`Display_lang`,'')='',t.`Display_lang`,l.`Display_lang`), l.`Description_lang`=IF(COALESCE(l.`Description_lang`,'')='',t.`Description_lang`,l.`Description_lang`);
INSERT INTO `item_sparse_locale` (`ID`,`locale`,`Description_lang`,`Display3_lang`,`Display2_lang`,`Display1_lang`,`Display_lang`,`VerifiedBuild`) SELECT t.`ID`,t.`locale`,t.`Description_lang`,t.`Display3_lang`,t.`Display2_lang`,t.`Display1_lang`,t.`Display_lang`,t.`VerifiedBuild` FROM `tmp_ruru_item_sparse_locale` t JOIN (SELECT DISTINCT `ID` FROM `item_sparse`) s ON s.`ID`=t.`ID` LEFT JOIN (SELECT DISTINCT `ID` FROM `item_sparse_locale` WHERE `locale`='ruRU') l ON l.`ID`=t.`ID` WHERE l.`ID` IS NULL;
DROP TEMPORARY TABLE `tmp_ruru_item_sparse_locale`;
